    data = sys.stdin.read().split()
    t = int(data[0])
    out = []
    for i in range(1, t + 1):
        s = data[i]
        target = 25
        sw = None
        for ch in s:
            c = ord(ch) - 97
            if c > target:
                continue
            if c == target:
                target -= 1
                if target < 0:
                    break
                continue
            sw = (c, target)
            break
        if sw is None:
            out.append(s)
        else:
            out.append(s.translate({97 + sw[0]: chr(97 + sw[1]), 97 + sw[1]: chr(97 + sw[0])}))
    print('\n'.join(out))

